import{_ as a,o as i,c as t,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy manuscript working draft","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","frontmatter":{"title":"Chainy manuscript working draft","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","source":"docs/manuscript-working-draft.md","category":"Research & evaluation","sourceUpdated":null,"outline":[2,3]},"headers":[],"relativePath":"content/docs/manuscript-working-draft.md","filePath":"content/docs/manuscript-working-draft.md"}'),o={name:"content/docs/manuscript-working-draft.md"};function r(s,e,c,d,l,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-manuscript-working-draft">Chainy manuscript working draft<a class="header-anchor" href="#chainy-manuscript-working-draft" aria-label="Link to this section">​</a></h1><p><strong>Capstone project title:</strong> Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)</p><p>This is a substantive starting draft for the official outline, based on current project decisions. Sean owns the academic document and school formatting; Miguel supports citations, figures and appendices. It is not submission-ready: verified related studies, actual implementation evidence, respondent details, approved instruments and collected results must still be supplied. Do not interpret prospective wording as completed work.</p><h2 id="chapter-1-introduction">Chapter 1 Introduction<a class="header-anchor" href="#chapter-1-introduction" aria-label="Link to this section">​</a></h2><h3 id="project-context">Project context<a class="header-anchor" href="#project-context" aria-label="Link to this section">​</a></h3><p>Chainy is proposed for learners aged 12–17, especially learners in low-income and remote communities with limited access to technology. Its purpose is foundational learning about Web3, artificial intelligence and blockchain through an offline Android educational game. Core lessons and progress saving do not require a network connection. Actual device access, learner prior knowledge and local instructional needs must be established through pilot-site coordination; the intended audience is a design priority, not an assumed survey finding about a particular school.</p><h3 id="purpose-and-description">Purpose and description<a class="header-anchor" href="#purpose-and-description" aria-label="Link to this section">​</a></h3><p>The system uses a tappable map with Web3, Blockchain and AI worlds leading to short guided lessons. Learners reason about digital identity and safe choices, order and link supplied records, investigate altered records, compare three simulated replicas, train a small local classifier from examples after prototype validation, and configure a short grid agent. These activities use simplified models with explicit limitations and preserve the approved toy-like 3D art direction. Full A–Z encyclopedia coverage, free spatial construction and walkable exploration are outside the revised pre-final scope. The game neither operates a public blockchain nor calls a cloud AI service.</p><p>Three levels organize the learning sequence: records and ordering; integrity and replica agreement; and example-based classification with output evaluation and agent behavior. Short missions, formative quizzes, feedback and progress badges connect player actions to learning objectives. Records are stored in SQLite on the Android device. A teacher-mediated export process supplies approved research evidence without requiring network access during gameplay.</p><h3 id="objectives-of-the-study">Objectives of the study<a class="header-anchor" href="#objectives-of-the-study" aria-label="Link to this section">​</a></h3><p>The general objective is to design, develop and evaluate an offline 3D educational game introducing selected blockchain and AI concepts to the target learners.</p><p>Specific proposed objectives are to implement the three learning levels and required interactive mechanics; provide explanations and assessment activities aligned with each objective; support reliable local progress and pseudonymous research evidence; verify usability and technical operation on selected Android devices; and evaluate observed learner understanding and user feedback using the school&#39;s approved research procedure.</p><p>These are project objectives, not statements that learning improvement has already occurred.</p><h3 id="scope-and-delimitation">Scope and delimitation<a class="header-anchor" href="#scope-and-delimitation" aria-label="Link to this section">​</a></h3><p>The first version uses English and targets a small supervised pilot. It is single-player and uses a bounded construction area, a limited component palette, three local logical replicas, a small explainable classifier and one agent challenge. SQLite stores local records; a learner code selects a local profile. Code entry does not provide verified remote authentication or cross-device progress synchronization.</p><p>Android 11+ and 4 GB physical RAM form a provisional test baseline; Android 10 compatibility and all minimum performance claims await device validation. Device capacity and required free installation space are distinct. No public cryptocurrency functions, online multiplayer, cloud inference or custom teacher web portal are planned for the pre-final implementation.</p><p>Findings will be limited to the actual learners, conditions, devices and instruments used. A supervised one-group design cannot by itself isolate a causal effect of the game from all other influences.</p><h3 id="significance-of-the-study">Significance of the study<a class="header-anchor" href="#significance-of-the-study" aria-label="Link to this section">​</a></h3><p>The proposed game may provide learners with observable examples of record integrity and data-driven classification; educators with a structured activity and locally collected evidence; Cryptita Plays with an offline instructional prototype; and developers with documented lessons about mobile educational-game design. These are intended contributions that the completed evaluation must substantiate.</p><h2 id="chapter-2-literature-and-technical-background">Chapter 2 Literature and technical background<a class="header-anchor" href="#chapter-2-literature-and-technical-background" aria-label="Link to this section">​</a></h2><p>A defensible literature review has not yet been supplied. Do not claim that no comparable work exists or turn technical manuals into evidence of educational effectiveness.</p><p>Sean&#39;s literature matrix must record each source&#39;s authors/year, population/age, learning objective, intervention, study design, findings, limitations and relevance to Chainy. Cover game-based learning for adolescents, blockchain concept instruction, introductory AI/data literacy, offline/mobile education, assessment and usability. Search for counterexamples to the proposed research gap; explain what Chainy actually contributes rather than claiming novelty from the combination alone.</p><p>Primary technical references support implementation facts:</p><ul><li><a href="https://docs.unity3d.com/6000.0/Documentation/Manual/system-requirements.html">Unity platform requirements</a>: engine compatibility, not Chainy&#39;s measured performance.</li><li><a href="https://www.sqlite.org/foreignkeys.html">SQLite foreign keys</a>: relational integrity configuration, not a research outcome.</li><li><a href="https://developer.android.com/training/data-storage/app-specific">Android storage</a>: local file lifecycle.</li><li><a href="https://developer.android.com/training/data-storage/shared/documents-files">Android document export</a>: user-mediated file access.</li><li><a href="https://scikit-learn.org/stable/modules/generated/sklearn.neighbors.NearestCentroid.html">Nearest centroid reference</a>: mathematical classifier behavior; not a requirement to embed Python.</li></ul><p>Working terms: block = a record container in the toy model; hash = deterministic data digest used in comparisons; replica = one logical ledger copy; consensus exercise = an explicitly simplified agreement rule; classifier = an example-trained mapping from defined features to labels; agent = an entity choosing actions under the visible policy; pseudonymous code = an identifier that may be linked by the authorized custodian; offline = core operation without a network connection. Validate the final technical definitions with the subject reviewer.</p><h2 id="chapter-3-design-and-methodology">Chapter 3 Design and methodology<a class="header-anchor" href="#chapter-3-design-and-methodology" aria-label="Link to this section">​</a></h2><p>The proposed development method is iterative delivery: define a bounded requirement, implement a small increment, test on a device, record feedback and update the design. The first increment proves one guided lesson, local storage and export; later increments add selected Web3 content, record validation, replicas, classification and agent behavior. Integration and regression occur before pilot use.</p><p>The planned evaluation separates system verification, usability feedback and learner concept assessment. A supervised pre/post approach with paired learner codes is recommended if the adviser approves measuring change. Population, sampling approach, sample size, inclusion criteria and exact instruments remain to be confirmed; no number or completed recruitment is invented.</p><p>Software/hardware/data requirements are defined in the <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a>, <a href="/Chainy-Docs/content/docs/hardware-validation.html">hardware plan</a>, <a href="/Chainy-Docs/content/docs/game-design.html">game design</a>, <a href="/Chainy-Docs/content/docs/technical-design.html">architecture</a> and <a href="/Chainy-Docs/attachments/docs/design/local-schema.sql">schema</a>. These artifacts should supply the official subsections for requirements, design, prototype and implementation plan once reviewed.</p><p>The teacher distributes approved APKs or prepared devices, issues learner codes, supervises sessions, and exports the approved records. The game remains offline. The study custodian controls any identity mapping, transfer destination and retention process. Device-only labels are insufficient for paired analysis on shared devices.</p><p>The <a href="/Chainy-Docs/content/docs/qa-evaluation.html">evaluation protocol</a> defines the proposed procedure, test matrix and analysis boundaries. The source wording ISO 2010 remains unresolved until the school provides the exact standard/version or questionnaire. Do not state ISO compliance from an unspecified tool.</p><h2 id="chapters-4-and-5-evidence-still-required">Chapters 4 and 5 Evidence still required<a class="header-anchor" href="#chapters-4-and-5-evidence-still-required" aria-label="Link to this section">​</a></h2><p>Chapter IV must contain actual preliminary and system evaluation results, with participant/device/build context, instrument versions, missing-data disposition, tables/figures and limitations. It cannot be completed truthfully from this design alone.</p><p>Chapter V must answer each objective using those results, distinguish implemented capability from measured effectiveness, and recommend improvements justified by observed limitations. Do not prewrite a conclusion that the game improved learning.</p><p>For each result table retain the approved source dataset location, transformation/analysis procedure and reproducible output; keep raw participant records out of GitHub. Use <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">the official manuscript and appendix map</a> to collect the front matter and appendices A–M. Actual approvals, UAT, MOU, photographs and certification must come from their responsible people and processes.</p></div>',1)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
